def semver_sort(versions):
    def parse_version(v):
        # Split off build metadata (ignore it)
        if '+' in v:
            v = v.split('+')[0]

        # Split into version and pre-release
        if '-' in v:
            version_part, prerelease_part = v.split('-', 1)
        else:
            version_part = v
            prerelease_part = None

        # Parse MAJOR.MINOR.PATCH
        parts = version_part.split('.')
        major = int(parts[0])
        minor = int(parts[1]) if len(parts) > 1 else 0
        patch = int(parts[2]) if len(parts) > 2 else 0

        # Parse pre-release identifiers
        if prerelease_part:
            identifiers = prerelease_part.split('.')
            prerelease_identifiers = []
            for identifier in identifiers:
                if identifier.isdigit():
                    prerelease_identifiers.append((0, int(identifier)))
                else:
                    prerelease_identifiers.append((1, identifier))
        else:
            prerelease_identifiers = None

        return (major, minor, patch, prerelease_identifiers)

    def compare_key(item):
        index, v = item
        major, minor, patch, prerelease_identifiers = parse_version(v)

        # Create sort key
        # For pre-release: None sorts after a list, so we need to handle that
        # If prerelease_identifiers is None, it means no pre-release (release version)
        # Release versions sort after pre-releases of the same version
        # So we use: (major, minor, patch, 1 if prerelease_identifiers is None else 0, prerelease_identifiers or (), index)

        if prerelease_identifiers is None:
            prerelease_key = (1,)  # Release version sorts after pre-release
        else:
            prerelease_key = (0, tuple(prerelease_identifiers))  # Pre-release sorts first

        return (major, minor, patch, prerelease_key, index)

    indexed_versions = list(enumerate(versions))
    sorted_versions = sorted(indexed_versions, key=compare_key)
    return [v for _, v in sorted_versions]

